-- The two checklists published on 2026-11-01: Planning the Holidays Before
-- They Arrive (Holidays) and Sleeping Well When You Work Nights (Shift Work).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-01`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('planning-the-holidays-before-they-arrive', 'Planning the Holidays Before They Arrive', 'For the weeks before the holidays, when invitations, money and expectations all land at once. It settles what you say yes to, what you spend, how long you stay, and where the ordinary days sit in among the gatherings.', 'Holidays', '["Decide now which invitations you will accept — a yes given in November is easier than a no in December.", "Pick the number you will spend before you shop — a figure set in advance survives the store.", "Name the one tradition that actually matters to you — the rest can go without anyone noticing.", "Plan for the empty chair if there is one — a first holiday without someone needs a plan, not a surprise.", "Agree your leaving time before you arrive — knowing when you go makes the hours in between bearable.", "Keep one ordinary day in the middle — laundry and a walk reset a week of gatherings.", "Write down the questions you know you will be asked — a prepared sentence beats being caught flat.", "Ask for one job to do at the gathering — a task in your hands is somewhere to put yourself.", "Put the week after it on the calendar now — the recovery is part of the holiday, not an extra."]'::jsonb, 'weekly', array['Family', 'Boundaries', 'Stress']::text[], 1, '2026-11-01T16:00:00+00:00'::timestamptz),
  ('sleeping-well-when-you-work-nights', 'Sleeping Well When You Work Nights', 'For anyone working nights or rotating shifts, when sleep has to happen at the wrong time of day. It sets one sleep window, makes the room dark, times the caffeine and the meals, and keeps an hour a week for people.', 'Shift Work', '["Pick one sleep window and keep it on days off — a body guesses badly when the hours keep moving.", "Make the bedroom fully dark before you lie down — blackout curtains and a mask beat willpower at noon.", "Wear sunglasses on the drive home — morning light tells your body to start the day instead.", "Put the phone in another room on silent — one delivery notification can cost you two hours.", "Eat your main meal before the shift, not during it — a heavy plate at three in the morning just sits there.", "Stop the caffeine six hours before your sleep window — it works long after you stop noticing it.", "Tell the household your sleep hours in writing — people respect a posted time more than a mentioned one.", "Keep one fixed hour a week with people you like — a night schedule quietly empties a calendar.", "Write down how many hours you actually got — a week of numbers shows what a feeling cannot.", "Ask about the pattern before you agree to swap a shift — a swap that flips your days costs more than a favor."]'::jsonb, 'daily', array['Sleep', 'Work', 'Body']::text[], 1, '2026-11-01T16:00:00+00:00'::timestamptz)
